create extension if not exists pgcrypto;create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),invite_code text unique not null,created_at timestamptz default now());create table if not exists public.memories(id uuid primary key default gen_random_uuid(),room_id uuid references public.rooms(id) on delete cascade,title text,event_date date,note text,image_data text,created_at timestamptz default now());alter table public.rooms enable row level security;alter table public.memories enable row level security;create policy "rooms read" on public.rooms for select using(true);create policy "rooms insert" on public.rooms for insert with check(true);create policy "memories read" on public.memories for select using(true);create policy "memories insert" on public.memories for insert with check(true);
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,device_id text not null,sender_name text not null,body text not null check(char_length(body)<=300),created_at timestamptz default now());alter table public.messages enable row level security;create policy "messages read" on public.messages for select using(true);create policy "messages insert" on public.messages for insert with check(true);

create table if not exists public.dm_profiles(friend_id text primary key,display_name text not null,avatar_data text,updated_at timestamptz default now());create table if not exists public.friendships(id uuid primary key default gen_random_uuid(),requester_id text not null references public.dm_profiles(friend_id) on delete cascade,addressee_id text not null references public.dm_profiles(friend_id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','rejected')),created_at timestamptz default now(),responded_at timestamptz,unique(requester_id,addressee_id),check(requester_id<>addressee_id));create table if not exists public.direct_messages(id uuid primary key default gen_random_uuid(),friendship_id uuid not null references public.friendships(id) on delete cascade,sender_id text not null references public.dm_profiles(friend_id),sender_name text,body text not null check(char_length(body)<=1000),created_at timestamptz default now(),read_at timestamptz);alter table public.dm_profiles enable row level security;alter table public.friendships enable row level security;alter table public.direct_messages enable row level security;drop policy if exists "dm_profiles all" on public.dm_profiles;drop policy if exists "friendships all" on public.friendships;drop policy if exists "direct_messages all" on public.direct_messages;create policy "dm_profiles all" on public.dm_profiles for all using(true) with check(true);create policy "friendships all" on public.friendships for all using(true) with check(true);create policy "direct_messages all" on public.direct_messages for all using(true) with check(true);do $$ begin alter publication supabase_realtime add table public.direct_messages; exception when duplicate_object then null; end $$;
